=== FILE: irq_ctrl_cov_tb.sv ===
// Coverage testbench for irq_ctrl.v (task prj-63d6b8e26c:coverage).
// Extends the approved idle testbench: after reset it drives every register,
// every source in level and edge mode, claims and acknowledges, W1C clears,
// enable masking, out-of-range acknowledges, a reset with live state, and a
// seeded pseudo-random phase. A reference model written from the register
// description in the RTL header predicts irq, irq_id and all four read values
// every cycle. Two instances run in parallel: N=8 (the default) and N=32, so
// read-data and claim-id bits that are constant at N=8 are exercised at N=32.
// Hit counters check that the stimulus reached each behaviour it targets.
`timescale 1ns / 1ps

module irq_ctrl_cov_harness #(
    parameter int          N    = 8,
    parameter logic [31:0] SEED = 32'h0000_0001
) (
    input  logic clk,
    output int   checks,
    output int   errors,
    output logic done
);
    logic         rst_n = 1'b0;
    logic [N-1:0] src   = '0;
    logic         we    = 1'b0;
    logic [1:0]   addr  = 2'd0;
    logic [31:0]  wdata = 32'd0;
    logic [31:0]  rdata;
    logic         irq;
    logic [4:0]   irq_id;

    int   n_checks = 0;
    int   n_errors = 0;
    logic finished = 1'b0;
    bit   checking = 1'b0;

    int hit_irq = 0;
    int hit_level = 0;
    int hit_edge = 0;
    int hit_ack = 0;
    int hit_w1c = 0;
    int hit_detect_wins = 0;
    int hit_masked = 0;
    int hit_ack_out_of_range = 0;
    int hit_high_id = 0;

    assign checks = n_checks;
    assign errors = n_errors;
    assign done   = finished;

    irq_ctrl #(.N(N)) dut (
        .clk(clk), .rst_n(rst_n), .src(src), .we(we), .addr(addr), .wdata(wdata),
        .rdata(rdata), .irq(irq), .irq_id(irq_id)
    );

    // Reference model.
    logic [N-1:0] m_enable, m_mode, m_pending, m_src_q;
    logic [N-1:0] m_detect, m_clear;
    logic [31:0]  m_onehot;

    always_comb begin
        // Level mode: a high level detects. Edge mode: high now and low at the previous edge.
        m_detect = src & ~(m_mode & m_src_q);
        // An acknowledge id at or above N falls outside the N-bit slice and clears nothing.
        m_onehot = 32'd1 << wdata[4:0];
        m_clear  = '0;
        if (we && addr == 2'd2) m_clear = wdata[N-1:0];
        if (we && addr == 2'd3) m_clear = m_onehot[N-1:0];
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            m_enable  <= '0;
            m_mode    <= '0;
            m_pending <= '0;
            m_src_q   <= '0;
        end else begin
            m_src_q   <= src;
            m_pending <= m_detect | (m_pending & ~m_clear);
            if (we && addr == 2'd0) m_enable <= wdata[N-1:0];
            if (we && addr == 2'd1) m_mode   <= wdata[N-1:0];
            if (|(m_pending & m_enable)) hit_irq <= hit_irq + 1;
            if (|(m_detect & ~m_mode)) hit_level <= hit_level + 1;
            if (|(m_detect & m_mode)) hit_edge <= hit_edge + 1;
            if (we && addr == 2'd3 && |(m_clear & m_pending & ~m_detect)) hit_ack <= hit_ack + 1;
            if (we && addr == 2'd2 && |(m_clear & m_pending & ~m_detect)) hit_w1c <= hit_w1c + 1;
            if (|(m_clear & m_detect)) hit_detect_wins <= hit_detect_wins + 1;
            if (|(m_pending & ~m_enable)) hit_masked <= hit_masked + 1;
            if (we && addr == 2'd3 && {27'd0, wdata[4:0]} >= N)
                hit_ack_out_of_range <= hit_ack_out_of_range + 1;
        end
    end

    function automatic logic [4:0] lowest_index(input logic [N-1:0] v);
        logic [4:0] idx;
        logic       found;
        idx   = 5'd0;
        found = 1'b0;
        for (int b = 0; b < N; b++) begin
            if (!found && v[b]) begin
                idx   = b[4:0];
                found = 1'b1;
            end
        end
        return idx;
    endfunction

    function automatic logic [31:0] xs32(input logic [31:0] x);
        logic [31:0] y;
        y = x ^ (x << 13);
        y = y ^ (y >> 17);
        y = y ^ (y << 5);
        return y;
    endfunction

    // Called at a falling edge: checks irq, irq_id and all four read values.
    task automatic check_regs();
        logic [N-1:0] act;
        logic         e_irq;
        logic [4:0]   e_id;
        logic [31:0]  e_rd;
        logic [1:0]   ad;
        act   = m_pending & m_enable;
        e_irq = |act;
        e_id  = lowest_index(act);
        we    = 1'b0;
        n_checks++;
        if (irq !== e_irq) n_errors++;
        n_checks++;
        if (irq_id !== e_id) n_errors++;
        if (e_id[4:3] != 2'b00) hit_high_id++;
        for (int a = 0; a < 4; a++) begin
            ad   = a[1:0];
            addr = ad;
            #1;
            e_rd = 32'd0;
            case (ad)
                2'd0:    e_rd[N-1:0] = m_enable;
                2'd1:    e_rd[N-1:0] = m_mode;
                2'd2:    e_rd[N-1:0] = m_pending;
                default: e_rd = {e_irq, 26'd0, e_id};
            endcase
            n_checks++;
            if (rdata !== e_rd) n_errors++;
        end
    endtask

    // One clock: check the state the previous edge produced, then apply the
    // inputs the next rising edge samples.
    task automatic cycle_r(input logic r, input logic w, input logic [1:0] a,
                           input logic [31:0] d, input logic [N-1:0] s);
        @(negedge clk);
        if (checking) check_regs();
        rst_n = r;
        we    = w;
        addr  = a;
        wdata = d;
        src   = s;
    endtask

    task automatic cycle(input logic w, input logic [1:0] a, input logic [31:0] d,
                         input logic [N-1:0] s);
        cycle_r(1'b1, w, a, d, s);
    endtask

    task automatic expect_true(input logic cond);
        n_checks++;
        if (!cond) n_errors++;
    endtask

    initial begin
        logic [N-1:0] all1;
        logic [N-1:0] one;
        logic [N-1:0] pa;
        logic [N-1:0] pb;
        logic [31:0]  w32;
        logic [31:0]  r1;
        logic [31:0]  r2;
        logic [31:0]  r3;
        logic [31:0]  rng;
        logic [4:0]   bi;
        all1   = '1;
        one    = '0;
        one[0] = 1'b1;
        w32    = 32'h5555_5555;
        pa     = w32[N-1:0];
        w32    = 32'hAAAA_AAAA;
        pb     = w32[N-1:0];
        rng    = SEED;

        // Power-on reset: two rising edges with rst_n low before checking starts.
        repeat (2) @(posedge clk);
        checking = 1'b1;

        // Reset held while writes and sources are applied: nothing may change.
        cycle_r(1'b0, 1'b1, 2'd0, 32'hFFFF_FFFF, all1);
        cycle_r(1'b0, 1'b1, 2'd1, 32'hFFFF_FFFF, all1);
        cycle_r(1'b0, 1'b1, 2'd2, 32'hFFFF_FFFF, '0);

        // 1. ENABLE and MODE written and read back, every wdata bit both ways.
        cycle(1'b1, 2'd0, 32'hFFFF_FFFF, '0);
        cycle(1'b1, 2'd0, 32'h0000_0000, '0);
        cycle(1'b1, 2'd0, 32'h5555_5555, '0);
        cycle(1'b1, 2'd0, 32'hAAAA_AAAA, '0);
        cycle(1'b1, 2'd1, 32'hFFFF_FFFF, '0);
        cycle(1'b1, 2'd1, 32'h0000_0000, '0);
        cycle(1'b1, 2'd1, 32'h5555_5555, '0);
        cycle(1'b1, 2'd1, 32'hAAAA_AAAA, '0);
        cycle(1'b1, 2'd1, 32'h0000_0000, '0);
        cycle(1'b1, 2'd0, 32'hFFFF_FFFF, '0);

        // 2. Level mode, one source at a time: detect, claim id, acknowledge.
        for (int b = 0; b < N; b++) begin
            bi = b[4:0];
            cycle(1'b0, 2'd0, 32'd0, one << b);
            cycle(1'b0, 2'd0, 32'd0, '0);
            cycle(1'b1, 2'd3, {27'h7FF_FFFF, bi}, '0);
        end
        cycle(1'b0, 2'd0, 32'd0, '0);

        // 3. A detection wins over an acknowledge or a W1C at the same edge.
        cycle(1'b0, 2'd0, 32'd0, all1);
        cycle(1'b1, 2'd3, 32'd2, all1);
        cycle(1'b1, 2'd2, 32'hFFFF_FFFF, all1);

        // 4. Priority walk: sources drop, the lowest is acknowledged each time.
        cycle(1'b0, 2'd0, 32'd0, '0);
        for (int b = 0; b < N; b++) begin
            w32 = b;
            cycle(1'b1, 2'd3, w32, '0);
        end
        cycle(1'b0, 2'd0, 32'd0, '0);

        // 5. W1C: all pending, clear the evens, a write of zero, clear the odds.
        cycle(1'b0, 2'd0, 32'd0, all1);
        cycle(1'b0, 2'd0, 32'd0, '0);
        cycle(1'b1, 2'd2, 32'h5555_5555, '0);
        cycle(1'b1, 2'd2, 32'h0000_0000, '0);
        cycle(1'b1, 2'd2, 32'hAAAA_AAAA, '0);

        // 6. Enable masking: pending while disabled raises no irq.
        cycle(1'b1, 2'd0, 32'h0000_0000, all1);
        cycle(1'b0, 2'd0, 32'd0, '0);
        cycle(1'b1, 2'd0, 32'h5555_5555, '0);
        cycle(1'b1, 2'd0, 32'hAAAA_AAAA, '0);
        w32 = 32'd0;
        w32[N-1] = 1'b1;
        cycle(1'b1, 2'd0, w32, '0);
        cycle(1'b1, 2'd2, 32'hFFFF_FFFF, '0);
        cycle(1'b1, 2'd0, 32'hFFFF_FFFF, '0);

        // 7. Edge mode on every source, then mixed mode.
        cycle(1'b1, 2'd1, 32'hFFFF_FFFF, '0);
        cycle(1'b0, 2'd0, 32'd0, all1);
        cycle(1'b1, 2'd2, 32'hFFFF_FFFF, all1);
        cycle(1'b0, 2'd0, 32'd0, all1);
        cycle(1'b0, 2'd0, 32'd0, '0);
        cycle(1'b1, 2'd2, 32'hFFFF_FFFF, all1);
        cycle(1'b1, 2'd3, 32'd0, all1);
        cycle(1'b0, 2'd0, 32'd0, pa);
        cycle(1'b0, 2'd0, 32'd0, pb);
        cycle(1'b0, 2'd0, 32'd0, all1);
        cycle(1'b1, 2'd2, 32'hFFFF_FFFF, '0);
        cycle(1'b1, 2'd1, 32'h5555_5555, '0);
        cycle(1'b0, 2'd0, 32'd0, all1);
        cycle(1'b1, 2'd2, 32'hFFFF_FFFF, all1);
        cycle(1'b0, 2'd0, 32'd0, '0);
        cycle(1'b1, 2'd2, 32'hFFFF_FFFF, '0);

        // 8. Acknowledge ids N to 31 name no source and change nothing (N < 32).
        cycle(1'b1, 2'd1, 32'h0000_0000, '0);
        cycle(1'b0, 2'd0, 32'd0, all1);
        cycle(1'b0, 2'd0, 32'd0, '0);
        for (int k = N; k < 32; k++) begin
            w32 = k;
            cycle(1'b1, 2'd3, w32, '0);
        end

        // 9. Reset with live state: pending, enable and mode return to zero.
        cycle(1'b1, 2'd1, 32'h5555_5555, '0);
        cycle_r(1'b0, 1'b0, 2'd0, 32'd0, all1);
        cycle_r(1'b0, 1'b0, 2'd0, 32'd0, all1);
        cycle(1'b0, 2'd0, 32'd0, '0);

        // 10. Seeded pseudo-random phase, checked against the model every cycle.
        cycle(1'b1, 2'd0, 32'hFFFF_FFFF, '0);
        for (int c = 0; c < 600; c++) begin
            rng = xs32(rng);
            r1  = rng;
            rng = xs32(rng);
            r2  = rng;
            rng = xs32(rng);
            r3  = rng;
            cycle(r1[0], r1[2:1], r2, r3[N-1:0]);
        end
        repeat (3) cycle(1'b0, 2'd0, 32'd0, '0);

        // The stimulus reached each behaviour it was written to reach.
        expect_true(hit_irq > 0);
        expect_true(hit_level > 0);
        expect_true(hit_edge > 0);
        expect_true(hit_ack > 0);
        expect_true(hit_w1c > 0);
        expect_true(hit_detect_wins > 0);
        expect_true(hit_masked > 0);
        if (N < 32) expect_true(hit_ack_out_of_range > 0);
        if (N > 8) expect_true(hit_high_id > 0);
        finished = 1'b1;
    end
endmodule

module irq_ctrl_cov_tb;
    logic clk = 1'b0;
    int   checks8;
    int   errors8;
    int   checks32;
    int   errors32;
    logic done8;
    logic done32;
    logic [8*64-1:0] nonce;
    logic [8*64-1:0] nonce_wd;

    always #5 clk = ~clk;

    irq_ctrl_cov_harness #(.N(8), .SEED(32'h1234_5678)) h8 (
        .clk(clk), .checks(checks8), .errors(errors8), .done(done8)
    );
    irq_ctrl_cov_harness #(.N(32), .SEED(32'h9E37_79B9)) h32 (
        .clk(clk), .checks(checks32), .errors(errors32), .done(done32)
    );

    initial begin
        int total_checks;
        int total_errors;
        while (!(done8 && done32)) @(posedge clk);
        total_checks = checks8 + checks32;
        total_errors = errors8 + errors32;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce,
                 (total_checks > total_errors ? total_checks - total_errors : 0), total_errors);
        $finish;
    end

    // Watchdog: a hung run ends as a failure.
    initial begin
        #1000000;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce_wd)) nonce_wd = "none";
        $display("NIRMAAN-SIM %0s 0 passed, 1 failed", nonce_wd);
        $finish;
    end
endmodule
=== END FILE ===
